    // 过滤描述与标签（屏蔽标签/屏蔽描述）
    u.novelFilter2 = function(novels) {
        let novels0 = novels.map(novel => novel.id)
        let captionBlockWords = getFromCache("captionBlockWords")
        if (captionBlockWords === null) captionBlockWords = []
