                novel.tags.unshift("长篇")
                if (novel.description === "") {
                    novel.description = firstNovel.description
                }
            }
        })
        // 收藏小说/追更系列 写入缓存
        util.saveNovels("likeNovels", likeNovels)
        util.saveNovels("watchedSeries", watchedSeries)
        util.debugFunc(() => {
            java.log(`处理小说完成`)
        })
