function handlerFactory() {
    if (baseUrl.includes("https://cdn.jsdelivr.net")) {
        return () => {updateSource(); return []}
    }
    if (!isLogin()) {
        return handlerNoLogin()
    }
    if (baseUrl.includes("/bookmark")) {
